+        return true;
+    }
+
+    @Override
+    public boolean isFirstFileAvailable(ConsumeQueueInterface consumeQueue) {
+        return true;
+    }
+
+    @Override
+    public long getTotalSize() {
+        return 0;
+    }
+}
