-            MappedByteBuffer mappedByteBuffer = curMappedFile.getMappedByteBuffer();
-
-            int slotPosition = hashCode % maxHashSlotNum;
-            int slotOffset = INDEX_FILE_HEADER_SIZE + slotPosition * INDEX_FILE_HASH_SLOT_SIZE;
