-                        return CompletableFuture.completedFuture(null);
-                    }
-
-                    int indexSize = slotBuffer.getInt();
-                    if (indexSize <= 0) {
-                        return CompletableFuture.completedFuture(null);
-                    }
-                    return fileSegment.readAsync(indexPosition, indexSize);
