+                if (itemBuffer.remaining() % COMPACT_INDEX_ITEM_SIZE != 0) {
+                    log.error("IndexStoreFile query from tiered storage return error item buffer, " +
+                        "key: {}, maxCount: {}, timestamp={}-{}", key, maxCount, beginTime, endTime);
+                    return result;
+                }
