+            // Make sure there is no read request here
+            fileReadWriteLock.writeLock().lock();
+            fileStatus.set(IndexStatusEnum.SEALED);
+        } catch (Exception e) {
+            log.error("IndexStoreFile change file status to sealed error, timestamp={}", this.getTimestamp());
