+                boolean diskOk = RocksDBMessageStore.this.runningFlags.getAndMakeLogicDiskFull();
+                if (diskOk) {
+                    RocksDBMessageStore.LOGGER.error("logics disk maybe full soon " + logicsRatio + ", so mark disk full");
